package main

import "net/http"

func serveUI(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" { http.NotFound(w, r); return }
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Content-Security-Policy", "default-src 'self'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'none'; frame-ancestors 'none'")
	_, _ = w.Write([]byte(neuraUI))
}

const neuraUI = `<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NEURA</title><style>
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#05070c;color:#eef5ff}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 50% 32%,#14254a 0,#090d18 32%,#05070c 68%);overflow-x:hidden}.app{min-height:100vh;display:grid;grid-template-rows:auto 1fr auto;padding:28px;max-width:1180px;margin:auto}.top{display:flex;justify-content:space-between;align-items:center}.brand{font-weight:800;letter-spacing:.34em;font-size:14px}.status{font-size:12px;color:#93a8c7;display:flex;gap:8px;align-items:center}.dot{width:8px;height:8px;border-radius:50%;background:#6df5c4;box-shadow:0 0 16px #6df5c4}.stage{display:grid;place-items:center;text-align:center;padding:24px 0}.entity-wrap{perspective:900px;position:relative;width:min(54vw,430px);aspect-ratio:1}.halo{position:absolute;inset:7%;border:1px solid #6bbcff55;border-radius:50%;box-shadow:inset 0 0 70px #458cff22,0 0 90px #2869ff25;animation:halo 7s ease-in-out infinite}.brain{position:absolute;inset:18%;transform-style:preserve-3d;animation:float 6s ease-in-out infinite;filter:drop-shadow(0 20px 35px #000b)}.lobe{position:absolute;width:62%;height:72%;top:13%;border-radius:48% 54% 46% 52%;background:radial-gradient(circle at 35% 25%,#d7f4ff 0,#68b8ff 12%,#4665d9 38%,#172050 68%,#080b22 100%);box-shadow:inset 12px 8px 20px #e7fbff44,inset -14px -10px 28px #020515aa,0 0 35px #4ca6ff44}.lobe:after{content:"";position:absolute;inset:13%;border-radius:inherit;background:repeating-radial-gradient(ellipse at 45% 45%,transparent 0 9px,#b8e7ff22 10px 12px);mix-blend-mode:screen}.left{left:3%;transform:rotateY(15deg) rotateZ(-7deg)}.right{right:3%;transform:rotateY(-15deg) rotateZ(7deg)}.core{position:absolute;inset:39%;border-radius:50%;background:#e8fbff;box-shadow:0 0 18px #fff,0 0 55px #5ad9ff,0 0 110px #566bff;animation:pulse 2.8s ease-in-out infinite}.entity-wrap[data-state=thinking] .brain{animation:think 1.3s ease-in-out infinite}.entity-wrap[data-state=success] .core{background:#baffdf;box-shadow:0 0 22px #fff,0 0 65px #55ffc2}.entity-wrap[data-state=error] .core{background:#ffb6bd;box-shadow:0 0 22px #fff,0 0 65px #ff5266}.title{margin-top:4px;font-size:clamp(26px,4vw,48px);font-weight:650;letter-spacing:-.035em}.subtitle{color:#8fa3c1;margin:8px auto 0;max-width:560px;line-height:1.5}.composer{width:min(760px,100%);margin:22px auto 0;display:flex;gap:10px;padding:8px;border:1px solid #91bfff2b;background:#0c1322cc;border-radius:20px;box-shadow:0 18px 55px #0008, inset 0 1px #ffffff0d;backdrop-filter:blur(18px)}input{flex:1;border:0;outline:0;background:transparent;color:#f4f8ff;padding:14px 16px;font-size:16px;min-width:0}button{border:0;border-radius:14px;padding:0 20px;background:linear-gradient(135deg,#78d9ff,#7774ff);color:#07101d;font-weight:800;cursor:pointer}.result{width:min(760px,100%);margin:14px auto 0;min-height:22px;color:#b9c8dd;text-align:left;font-size:14px;white-space:pre-wrap}.recovery{width:min(760px,100%);margin:18px auto 0;padding:14px;border:1px solid #91bfff24;border-radius:18px;background:#09111fbb;box-shadow:inset 0 1px #ffffff0a;text-align:left}.recovery-head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:10px}.recovery-head strong{display:block;font-size:13px;letter-spacing:.06em}.recovery-head span{display:block;color:#6f829f;font-size:11px;margin-top:3px}.task-list{display:grid;gap:8px}.task{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:10px 12px;border:1px solid #ffffff0c;border-radius:13px;background:#0d1728}.task-main{min-width:0}.task-id{font-size:13px;font-weight:700;overflow:hidden;text-overflow:ellipsis}.task-meta{font-size:11px;color:#778aa8;margin-top:4px}.badge{display:inline-block;margin-left:7px;padding:2px 6px;border-radius:999px;background:#263550;color:#b9c9df;font-size:9px;text-transform:uppercase;letter-spacing:.06em}.badge.blocked{background:#4b3421;color:#ffd29b}.badge.manual_review{background:#4a2934;color:#ffb8ca}.task-actions{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}.memory-search{display:flex;gap:8px;margin-bottom:10px}.memory-search input{padding:10px 12px;border:1px solid #ffffff12;border-radius:12px;background:#0d1728}.memory-text{font-size:12px;line-height:1.45;color:#c2d0e5}.memory-meta{font-size:10px;color:#7185a3;margin-top:5px;text-transform:uppercase;letter-spacing:.05em}.mini{min-height:34px;padding:0 10px;border-radius:10px;font-size:11px}.mini.secondary{background:#18243a;color:#b7c9e4;border:1px solid #ffffff10}.empty{padding:9px;color:#667995;font-size:12px}.foot{display:flex;justify-content:center;gap:18px;color:#64738b;font-size:11px;padding-top:20px}@keyframes float{50%{transform:translateY(-10px) rotateY(5deg)}}@keyframes halo{50%{transform:scale(1.04);opacity:.72}}@keyframes pulse{50%{transform:scale(1.16)}}@keyframes think{25%{transform:rotateY(8deg) translateY(-7px)}75%{transform:rotateY(-8deg) translateY(3px)}}@media(max-width:620px){.app{padding:20px}.entity-wrap{width:78vw}.composer{border-radius:17px}.task{align-items:flex-start;flex-direction:column}.task-actions{justify-content:flex-start}.foot{gap:10px;flex-wrap:wrap}}
</style></head><body><main class="app"><header class="top"><div class="brand">NEURA</div><div class="status"><span class="dot"></span><span id="online">connessione…</span></div></header><section class="stage"><div><div class="entity-wrap" id="entity" data-state="idle" aria-label="Entità NEURA"><div class="halo"></div><div class="brain"><div class="lobe left"></div><div class="lobe right"></div><div class="core"></div></div></div><div class="title">Come posso aiutarti?</div><p class="subtitle">NEURA lavora localmente, pianifica e verifica le azioni prima di completarle.</p><form class="composer" id="form"><input id="goal" autocomplete="off" placeholder="Chiedi qualcosa a NEURA…" aria-label="Richiesta"><button>Invia</button></form><div class="result" id="result" aria-live="polite"></div><section class="recovery" aria-label="Recovery task"><div class="recovery-head"><div><strong>RECOVERY TASK</strong><span>Riprendi i task bloccati senza ritentare mutazioni alla cieca.</span></div><button type="button" class="mini secondary" id="refreshTasks">Aggiorna</button></div><div class="task-list" id="tasks"><div class="empty">Nessun task da mostrare.</div></div></section><section class="recovery" aria-label="Memoria NEURA"><div class="recovery-head"><div><strong>MEMORIA ATTIVA</strong><span>Richiama la verità corrente e ispeziona lo storico delle sostituzioni.</span></div></div><form class="memory-search" id="memoryForm"><input id="memoryQuery" autocomplete="off" placeholder="Cerca nella memoria…" aria-label="Cerca memoria"><button type="submit" class="mini">Cerca</button></form><div class="task-list" id="memories"><div class="empty">Memoria non ancora caricata.</div></div></section></div></section><footer class="foot"><span>LOCAL FIRST</span><span>VERIFIED ACTIONS</span><span>ZERO API OBBLIGATORIE</span></footer></main><script>
const e=document.getElementById('entity'),o=document.getElementById('online'),r=document.getElementById('result'),f=document.getElementById('form'),g=document.getElementById('goal'),t=document.getElementById('tasks'),refresh=document.getElementById('refreshTasks'),mf=document.getElementById('memoryForm'),mq=document.getElementById('memoryQuery'),ml=document.getElementById('memories');
const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
async function status(){try{const x=await fetch('/status');if(!x.ok)throw 0;const j=await x.json();o.textContent='online · '+j.version;e.dataset.state='idle'}catch(_){o.textContent='offline';e.dataset.state='error'}}
async function loadMemory(q=''){try{const x=await fetch('/memory?q='+encodeURIComponent(q)+'&limit=6');if(!x.ok)throw new Error('Memoria non disponibile');const j=await x.json(),items=j.items||[];if(!items.length){ml.innerHTML='<div class="empty">Nessuna memoria rilevante.</div>';return}ml.innerHTML=items.map(x=>'<div class="task" data-memory-id="'+esc(x.id)+'"><div class="task-main"><div class="memory-text">'+esc(x.text)+'</div><div class="memory-meta">'+esc(x.type||'legacy')+' · '+esc(x.provenance||'sconosciuta')+(x.supersedes?' · sostituisce '+esc(x.supersedes):'')+'</div></div><div class="task-actions">'+(x.supersedes?'<button type="button" class="mini secondary" data-memory-history>Storico</button>':'')+'</div></div>').join('')}catch(err){ml.innerHTML='<div class="empty">'+esc(err.message)+'</div>'}}
async function loadTasks(){try{const x=await fetch('/tasks?limit=6');if(!x.ok)throw new Error('Task non disponibili');const j=await x.json(),items=j.items||[];if(!items.length){t.innerHTML='<div class="empty">Nessun task da mostrare.</div>';return}t.innerHTML=items.map(x=>{const total=x.plan&&x.plan.steps?x.plan.steps.length:0,progress=(x.next_step||0)+'/'+total;let actions='';if(x.state==='blocked')actions='<button type="button" class="mini" data-action="retry">Riprova sicuro</button>';if(x.state==='manual_review')actions='<button type="button" class="mini secondary" data-action="repeat">Ripeti azione</button><button type="button" class="mini" data-action="verified">Effetto verificato</button>';return '<div class="task" data-id="'+esc(x.id)+'" data-generation="'+x.generation+'"><div class="task-main"><div class="task-id">'+esc(x.id)+'<span class="badge '+esc(x.state)+'">'+esc(x.state)+'</span></div><div class="task-meta">step '+progress+' · recovery '+(x.recovery_count||0)+(x.last_error?' · '+esc(x.last_error):'')+'</div></div><div class="task-actions">'+actions+'</div></div>'}).join('')}catch(err){t.innerHTML='<div class="empty">'+esc(err.message)+'</div>'}}
f.addEventListener('submit',async ev=>{ev.preventDefault();const goal=g.value.trim();if(!goal)return;e.dataset.state='thinking';r.textContent='NEURA sta lavorando…';try{const x=await fetch('/command',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({goal})});const j=await x.json();if(!x.ok)throw new Error(j.error||j.status||'Errore');e.dataset.state='success';r.textContent=j.answer||j.summary||j.message||JSON.stringify(j,null,2)}catch(err){e.dataset.state='error';r.textContent=err.message}finally{loadTasks();loadMemory(mq.value.trim());setTimeout(()=>{if(e.dataset.state!=='error')e.dataset.state='idle'},1800)}});
t.addEventListener('click',async ev=>{const b=ev.target.closest('button[data-action]');if(!b)return;const row=b.closest('.task'),id=row.dataset.id,generation=Number(row.dataset.generation),action=b.dataset.action;if((action==='repeat'||action==='verified')&&!confirm(action==='verified'?'Confermi che l’effetto della mutazione è già avvenuto e verificato?':'Confermi che l’effetto NON è verificato e vuoi rendere il task nuovamente eseguibile?'))return;e.dataset.state='thinking';try{const resolve=action!=='retry',x=await fetch('/tasks/'+encodeURIComponent(id)+(resolve?'/resolve':'/retry'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(resolve?{generation,effect_verified:action==='verified'}:{generation})}),j=await x.json();if(!x.ok)throw new Error(j.error||'Recovery fallita');e.dataset.state='success';r.textContent='Recovery aggiornata per '+id}catch(err){e.dataset.state='error';r.textContent=err.message}finally{await loadTasks();setTimeout(()=>{if(e.dataset.state!=='error')e.dataset.state='idle'},1600)}});
mf.addEventListener('submit',ev=>{ev.preventDefault();loadMemory(mq.value.trim())});
ml.addEventListener('click',async ev=>{const b=ev.target.closest('button[data-memory-history]');if(!b)return;const row=b.closest('[data-memory-id]'),id=row.dataset.memoryId;e.dataset.state='thinking';try{const x=await fetch('/memory/history?id='+encodeURIComponent(id)),j=await x.json();if(!x.ok)throw new Error(j.error||'Storico non disponibile');r.textContent='Storico memoria:\n'+(j.items||[]).map((m,i)=>(i+1)+'. '+m.text+' ['+(m.type||'legacy')+']').join('\n');e.dataset.state='success'}catch(err){e.dataset.state='error';r.textContent=err.message}finally{setTimeout(()=>{if(e.dataset.state!=='error')e.dataset.state='idle'},1600)}});
refresh.addEventListener('click',loadTasks);status();loadTasks();loadMemory();
</script></body></html>`
